 @Test void workOrderExpenseLinkKeepsNOIOnSingleCanonicalExpense()throws Exception{
  Owner owner=Fixtures.owner(ctx);Property property=Fixtures.property(ctx,owner);MaintenanceRequest request=new MaintenanceRequest();request.setPropertyId(property.getPropertyId());request.setTitle("Replace leaking valve");request.setReportedDate(TODAY);request=ctx.maintenance().open(request);ctx.maintenance().changeStatus(request.getRequestId(),MaintenanceStatus.IN_PROGRESS,null);
  Vendor vendor=ctx.vendors().save(new Vendor(null,"Test Plumbing",VendorCategory.PLUMBING,"555-0100",null,null,null,true));
  WorkOrder draft=ctx.workOrders().create(new WorkOrder(null,property.getPropertyId(),request.getRequestId(),null,null,"Replace valve","Unit 2 sink",MaintenancePriority.HIGH,TODAY,WorkOrderStatus.DRAFT,new BigDecimal("100.00"),null,null,null,null,null,null));
  ctx.workOrders().assign(draft.id(),vendor.id());ctx.workOrders().transition(draft.id(),WorkOrderStatus.IN_PROGRESS,null,null);ctx.workOrders().transition(draft.id(),WorkOrderStatus.COMPLETED,new BigDecimal("90.00"),"Valve replaced");
  MaintenanceRequest editable=ctx.maintenance().get(request.getRequestId());editable.setCost(new BigDecimal("90.00"));ctx.maintenance().update(editable);ctx.maintenance().changeStatus(request.getRequestId(),MaintenanceStatus.RESOLVED,TODAY);
  Expense expense=new Expense();expense.setPropertyId(property.getPropertyId());expense.setMaintenanceRequestId(request.getRequestId());expense.setCategory(ExpenseCategory.REPAIRS);expense.setAmount(new BigDecimal("90.00"));expense.setExpenseDate(TODAY);expense.setDescription("Valve replacement");expense.setPaymentMethod(PaymentMethod.BANK_TRANSFER);expense=ctx.expenses().create(expense);
  WorkOrder linked=ctx.workOrders().linkExpense(draft.id(),expense.getExpenseId());assertEquals(expense.getExpenseId(),linked.expenseId());var report=ctx.profitability().report(TODAY,TODAY,property.getPropertyId());assertEquals(new BigDecimal("90.00"),report.expenses());assertEquals(new BigDecimal("0.00"),report.maintenanceFromRequests());var performance=ctx.workOrders().vendorPerformance(TODAY,TODAY);assertEquals(1,performance.size());assertEquals(1,performance.getFirst().completedOrders());assertEquals(100,performance.getFirst().onTimePercent().intValue());assertEquals(new BigDecimal("90.00"),performance.getFirst().actualCost());
 }
